__NUXT_JSONP__("/ar/firstday-at-mli", (function(a,b){return {data:[{details:{slug:"ar",pageTitle:"اليوم الأول في معهد منتور | Mentor Language Institute",pageDescription:a,title:"اليوم الأول في معهد منتور",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffirst-day-at-mli\u002Fmli-signup.jpg",categories:[{title:"مرحبا بكم في معهد منتور للغات!",description:[a,"اللقاء التعريفي سوف يوفر لك المعلومات الهامة و الضرورية للتعرف أكثر على برامجنا, كما أنه سوف تتسنى لك الفرصة للحصول على إجابة على تساؤلاتك بخصوص لوائح الهجرة، و قوانين المعهد ، وكذلك تساعدك على تحقيق جميع الأهداف الأكاديمية الخاصة بك.","سوف تتلقى الترحيب من الجميع منموظفي مكتب القبول لدينا، و سوف تلتقي و تتعرف على معلمينا ومكتب الاستقبال، الموظفين الإداريين والإدارة"],dates:["＜تاريخ بدء كل فصل＞","- May 22nd, 2023 \u003Cbr\u002F\u003E - June 20th, 2023 \u003Cbr\u002F\u003E - July 17th, 2023 \u003Cbr\u002F\u003E - August 14th, 2023 \u003Cbr\u002F\u003E - September 11th, 2023 \u003Cbr\u002F\u003E - October 10th, 2023 \u003Cbr\u002F\u003E - November 6th, 2023 \u003Cbr\u002F\u003E - December 4th, 2023 \u003Cbr\u002F\u003E - January 8th, 2024 \u003Cbr\u002F\u003E - February 5th, 2024 \u003Cbr\u002F\u003E - March 4th, 2024","يبدأ اللقاء التعريفي في تمام الساعة الواحدة مساء"],groups:[{title:"اللقاء التعريفي و اختبار تحديد المستوى",listType:"table",lists:[{key:"1:00pm – 1:30pm",value:"التسجيل الأوراق"},{key:"1:30pm – 2:00pm",value:"اللقاء التعريفي الأكاديمي"},{key:"2:00pm – 3:00pm",value:"إختبار تحديد المتسوى"},{key:"3:15pm – 3:35pm",value:"سياسات المدرسة\u002Fمعهد، قواعد الهجرة"},{key:"3:35pm – 3:50pm",value:"خدمة التحويل إلى الكلية"},{key:"3:50pm – 4:00pm",value:"الأنشطة والإسكان"},{key:"4:00pm – 4:10pm",value:"إختبار تحديد المستوى الورقي و المحادثة"},{key:"4:10pm – 4:20pm",value:b}]},{title:"ما لجلب معك في اليوم الأول",lists:["جواز سفر (إذا كنت حامل تأشيرة طالب)","I-20 (إذا كنت حامل تأشيرة طالب)","ورقة وقلم","رسوم الكتاب المدرسي ودفع الرسوم الدراسية"]}]},{title:"تفاصيل",groups:[{title:"جدول اللقاء التعريفي",description:["سوف تقوم بتعبئة الأوراق اللازمة لإتمام عملية التسجيل\u003Cbr \u002F\u003E بعد ذلك، سيقدم المدير الأكاديمي أو منسق البرنامج عرضا حول برامجنا المختلفة،\u003Cbr \u002F\u003Eوالقواعد الصفية، وكيفية النجاح في دراستك من أجل الانتقال من مستوى إلى آخر، ومن برنامج إلى آخر."]},{title:"اختبار الكتابي والمقابلة",description:["بعد الإنتهاء من اللقاء التعريفي, سوف تبدأ \" إختبار تحديد المستوى\" وهو مايقارب 80 سؤالا مع تقييم الاستماع و الكتابة, هذا الإختبار يشمل قواهعد اللغة و المفردات و القراءة و الفهم, مدة الإختبار ستين دقيقة, بعد الإختبار سوف يكون هناك مقابلة مع إحد معلميينا لتقييم مستوى اللغة في الكلام, هذا الاختبار سوف يحدد البرنامج الأنسب لك بناء على مهاراتك و أهدافك."]},{title:b,description:["بعد الإنتهاء من اللقاء التعريفي و إختبار تحديد المستوى سوف يتسنى للطلاب شراء الكتب المدرسية من موظفي الإستقبال, الذين ستواجدون للإجابة على أي أسألة أو اسفتسارات إضافية"]}]}],dir:"\u002Ffirstday-at-mli",path:"\u002Ffirstday-at-mli\u002Far",extension:".json",createdAt:"2026-10-22T16:31:29.249Z",updatedAt:"2025-05-26T12:06:27.754Z"}}],fetch:{},mutations:void 0}}("في معهد مينتور لدينا لقاء تعريفي للطلاب الجدد في بداية كل فصل دراسي أي بمعنى كل أربع أسابيع","شراء الكتب المدرسية")));